<?php

declare(strict_types=1);

require_once dirname(__DIR__) . '/includes/bootstrap.php';
require_once dirname(__DIR__) . '/includes/auth.php';
require_once dirname(__DIR__) . '/includes/admin-auth.php';

$metrics = ['revenue' => 0, 'orders' => 0, 'customers' => 0, 'products' => 0, 'pending_orders' => 0, 'returns' => 0, 'refunds' => 0, 'low_stock' => 0];
$admin = null;
$error = '';
try {
    $connection = database_connection();
    $admin = admin_require($connection);
    $metrics['revenue'] = (float) $connection->query("SELECT COALESCE(SUM(grand_total), 0) FROM orders WHERE status IN ('confirmed', 'processing', 'shipped', 'delivered', 'completed')")->fetchColumn();
    $metrics['orders'] = (int) $connection->query('SELECT COUNT(*) FROM orders')->fetchColumn();
    $metrics['customers'] = (int) $connection->query('SELECT COUNT(*) FROM users')->fetchColumn();
    $metrics['products'] = (int) $connection->query("SELECT COUNT(*) FROM products WHERE status <> 'archived'")->fetchColumn();
    $metrics['pending_orders'] = (int) $connection->query("SELECT COUNT(*) FROM orders WHERE status IN ('pending', 'confirmed', 'processing')")->fetchColumn();
    $metrics['returns'] = (int) $connection->query("SELECT COUNT(*) FROM returns WHERE status IN ('requested', 'approved', 'received', 'inspecting')")->fetchColumn();
    $metrics['refunds'] = (int) $connection->query("SELECT COUNT(*) FROM refunds WHERE status = 'pending'")->fetchColumn();
    $metrics['low_stock'] = (int) $connection->query('SELECT COUNT(*) FROM inventory WHERE quantity_on_hand - quantity_reserved <= reorder_level')->fetchColumn();
} catch (Throwable $exception) { error_log($exception->getMessage()); $error = 'Dashboard data is temporarily unavailable.'; }
