revenue'], 2)], ['orders', 'Orders', (string) $metrics['orders']], ['customers', 'Customers', (string) $metrics['customers']], ['products', 'Products', (string) $metrics['products']], ['pending_orders', 'Pending orders', (string) $metrics['pending_orders']], ['returns', 'Open returns', (string) $metrics['returns']], ['refunds', 'Pending refunds', (string) $metrics['refunds']], ['low_stock', 'Low stock', (string) $metrics['low_stock']]]; foreach ($cards as $card): ?><article class="admin-metric"><span><?= escape_html($card[1]) ?></span><strong><?= escape_html($card[2]) ?></strong></article><?php endforeach; ?></section><section class="admin-panel"><div class="section__header"><div><p class="eyebrow">Sales overview</p><h2>Operational pulse.</h2></div><span class="badge">Live database metrics</span></div><div class="admin-quick-links"><a href="<?= escape_html(base_url('admin/module.php?name=orders')) ?>"><strong>Review pending orders</strong><span><?= escape_html((string) $metrics['pending_orders']) ?> need attention</span></a><a href="<?= escape_html(base_url('admin/module.php?name=inventory')) ?>"><strong>Check low stock</strong><span><?= escape_html((string) $metrics['low_stock']) ?> products at or below reorder level</span></a><a href="<?= escape_html(base_url('admin/module.php?name=returns')) ?>"><strong>Review returns</strong><span><?= escape_html((string) $metrics['returns']) ?> active requests</span></a></div></section></main></body></html>